package com.habitpro.model;import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.mapping.Document;import java.time.Instant;@Document("sticky_notes")public class StickyNote{@Id private String id;private String userId,title,content,deadline,remindAt,color;private boolean pinned;private Instant createdAt=Instant.now();public String getId(){return id;}public String getUserId(){return userId;}public void setUserId(String v){userId=v;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getContent(){return content;}public void setContent(String v){content=v;}public String getDeadline(){return deadline;}public void setDeadline(String v){deadline=v;}public String getRemindAt(){return remindAt;}public void setRemindAt(String v){remindAt=v;}public String getColor(){return color;}public void setColor(String v){color=v;}public boolean isPinned(){return pinned;}public void setPinned(boolean v){pinned=v;}public Instant getCreatedAt(){return createdAt;}}